 @Test void dispatchMovementCountsOnlySelected20AndObserved10KeepsTransit10(){allow("100");allowDispatch();String allocation=reserve("20","20");run("pickQuantity",map("allocationId",allocation),0);var out=run("dispatchQuantity",map("allocationId",allocation,"transitPlaceId",transit,"occurredAt",now.toString(),"evidenceRef","synthetic dispatch"),1);String dispatch=effects(out).get("dispatchId").toString();assertEquals(0,new BigDecimal("20").compareTo(jdbc.queryForObject("SELECT SUM(quantity) FROM mulino_inventory_QuantityMovements WHERE kind='DISPATCH'",BigDecimal.class)));var delivered=tx(()->physical.observeDelivery(c(),dispatch,id(),new BigDecimal("20"),new BigDecimal("10"),now,id()));assertEquals(0,new BigDecimal("10").compareTo((BigDecimal)delivered.get("legitimateQuantity")));assertEquals(0,new BigDecimal("10").compareTo(jdbc.queryForObject("SELECT SUM(s.quantity) FROM mulino_inventory_QuantitySegments s JOIN mulino_inventory_Places p ON s.placeId=p.ID AND s.organizationId=p.organizationId WHERE s.retiredAt IS NULL AND p.kind='TRANSIT'",BigDecimal.class)));assertEquals(0,new BigDecimal("10").compareTo(jdbc.queryForObject("SELECT SUM(quantity) FROM mulino_inventory_QuantityMovements WHERE kind='DELIVERY'",BigDecimal.class)));}
 // Two real transactions hold the common physical fence before the second command starts.
 // The barrier fixes the serial order; it does not rely on timing or thread sleeps.
 Map<String,Object> race(Map<String,Object> first,Map<String,Object> second)throws Exception{
  var firstPid=new java.util.concurrent.atomic.AtomicInteger();var firstLocked=new java.util.concurrent.CountDownLatch(1);var secondStarted=new java.util.concurrent.CountDownLatch(1);var release=new java.util.concurrent.CountDownLatch(1);var security=SecurityContextHolder.getContext().getAuthentication();var pool=java.util.concurrent.Executors.newFixedThreadPool(2);
  try{var one=pool.submit(()->{SecurityContextHolder.getContext().setAuthentication(security);return tx(()->{inventory.fence(c(),stock.fences(inventory.current(c(),"QuantitySegments",segment)));firstPid.set(jdbc.queryForObject("SELECT pg_backend_pid()",Integer.class));firstLocked.countDown();await(release);return apply(first);});});assertTrue(firstLocked.await(10,java.util.concurrent.TimeUnit.SECONDS));var two=pool.submit(()->{SecurityContextHolder.getContext().setAuthentication(security);secondStarted.countDown();return apply(second);});assertTrue(secondStarted.await(10,java.util.concurrent.TimeUnit.SECONDS));long deadline=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(5);boolean waiting=false;while(System.nanoTime()<deadline){waiting=jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM pg_stat_activity WHERE ? = ANY(pg_blocking_pids(pid)))",Boolean.class,firstPid.get());if(waiting)break;Thread.onSpinWait();}assertTrue(waiting,"Second PostgreSQL transaction must be blocked by first before barrier release");release.countDown();assertEquals("APPLIED",one.get(20,java.util.concurrent.TimeUnit.SECONDS).get("outcome"));return two.get(20,java.util.concurrent.TimeUnit.SECONDS);}finally{release.countDown();pool.shutdownNow();}
 }
 void await(java.util.concurrent.CountDownLatch latch){try{if(!latch.await(10,java.util.concurrent.TimeUnit.SECONDS))throw new IllegalStateException("Barrier timeout");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}}
 @Test void v2SplitFirstRejectsStaleParentReserveAndPreservesExisting40Once()throws Exception{allow("60");String old=reserve("0","40");var split=envelope("splitQuantity",map("segmentId",segment,"quantities",List.of("30","30"),"unit","EA","occurredAt",now.toString(),"evidenceRef","synthetic split"),0);var reserve=envelope("reserveQuantity",map("segmentId",segment,"salesLineId",salesLine,"startQuantity","40","quantity","20","unit","EA"),0);assertEquals("REJECTED",race(split,reserve).get("outcome"));assertEquals(0,new BigDecimal("40").compareTo(jdbc.queryForObject("SELECT SUM(quantity) FROM mulino_inventory_SegmentAllocations WHERE state='EXECUTABLE'",BigDecimal.class)));assertEquals("REPLACED",jdbc.queryForObject("SELECT state FROM mulino_inventory_SegmentAllocations WHERE ID=?",String.class,old));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM mulino_inventory_SegmentAllocations WHERE segmentId=? AND state='EXECUTABLE'",Integer.class,segment));assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM mulino_inventory_GenealogyEdges WHERE sourceId=?",Integer.class,segment));}
