 Map<String,Object> preparedHold(String quantity){var slots=permission("placeHold","QC",quantity);slots.put("action","ALL");String doc=evidence(slots,"HOLD");slots.remove("operation");slots.remove("sourceDecisionId");slots.remove("sourceVersion");slots.putAll(map("evidenceId",doc,"reason","Independent current hold","nextCheckAt",now.plusSeconds(60).toString()));return envelope("placeHold",slots,0);}
 @Test void v3HoldCommitsAfterEligibleQueryBeforeDispatchPhysicalEffectZero()throws Exception{allow("100");allowDispatch();String allocation=reserve("0","20");run("pickQuantity",map("allocationId",allocation),0);var hold=preparedHold("100");assertEquals(0,new BigDecimal("100").compareTo(assess().eligibleQuantity()));var dispatch=envelope("dispatchQuantity",map("allocationId",allocation,"transitPlaceId",transit,"occurredAt",now.toString(),"evidenceRef","synthetic dispatch"),1);assertEquals("REJECTED",race(hold,dispatch).get("outcome"));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM mulino_inventory_Dispatches",Integer.class));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM mulino_inventory_QuantityMovements",Integer.class));assertEquals("SUSPENDED",jdbc.queryForObject("SELECT state FROM mulino_inventory_SegmentAllocations WHERE ID=?",String.class,allocation));}
 @Test void v3DispatchFirstKeepsHistoryAndNewHoldResponsibilityAndOldReleaseCannotClearIt()throws Exception{allow("100");allowDispatch();String allocation=reserve("0","20");run("pickQuantity",map("allocationId",allocation),0);var hold=preparedHold("100");hold.put("expectedRevision",1);var dispatch=envelope("dispatchQuantity",map("allocationId",allocation,"transitPlaceId",transit,"occurredAt",now.toString(),"evidenceRef","synthetic dispatch"),1);assertEquals("APPLIED",race(dispatch,hold).get("outcome"));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM mulino_inventory_Dispatches",Integer.class));assertEquals("CONSUMED",jdbc.queryForObject("SELECT state FROM mulino_inventory_SegmentAllocations WHERE ID=?",String.class,allocation));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM mulino_work_read_ObligationReferences WHERE kind='QUALITY_REVIEW' AND ownerId=?",Integer.class,actor));String restriction=jdbc.queryForObject("SELECT ID FROM mulino_inventory_Restrictions",String.class);String doc=evidence(map("segmentId",segment,"operation","releaseHold","restrictionId",restriction),"OLD_RELEASE");run("releaseHold",map("restrictionId",restriction,"evidenceId",doc,"reason","Referenced old hold resolved"),0);var newer=preparedHold("100");newer.put("expectedRevision",1);assertEquals("APPLIED",apply(newer).get("outcome"));assertEquals("REJECTED",apply(envelope("releaseHold",map("restrictionId",restriction,"evidenceId",doc,"reason","Late old release"),0)).get("outcome"));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM mulino_inventory_Restrictions WHERE state='ACTIVE'",Integer.class));String dispatchId=jdbc.queryForObject("SELECT ID FROM mulino_inventory_Dispatches",String.class);var actual=tx(()->physical.observeDelivery(c(),dispatchId,id(),BigDecimal.ZERO,new BigDecimal("20"),now,id()));assertEquals(BigDecimal.ZERO,actual.get("legitimateQuantity"));assertEquals(0,new BigDecimal("20").compareTo((BigDecimal)actual.get("quantity")));}

 @Test void uncertainMergeNeverDropsAllocationResponsibilityOrInventsExecutableSubset(){allow("100");reserve("0","40");String uncertain=id();record("mulino_inventory_QuantitySegments",uncertain,map("itemId",item,"lotId",lot,"identificationStatus","CONFIRMED","quantity",new BigDecimal("20"),"unit","EA","placeId",place,"controlScope","quality","validFrom",Timestamp.from(now.minusSeconds(10)),"mixtureStatus","UNCERTAIN_MIXTURE","ownerId",actor,"custodianId",actor));String merged=tx(()->stock.merge(c(),List.of(segment,uncertain),now,"synthetic uncertain merge",id()));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM mulino_inventory_SegmentAllocations WHERE state='EXECUTABLE'",Integer.class));assertEquals(0,new BigDecimal("40").compareTo(jdbc.queryForObject("SELECT SUM(quantity) FROM mulino_inventory_SegmentAllocations WHERE state='SUSPENDED'",BigDecimal.class)));assertEquals("UNCERTAIN_MIXTURE",jdbc.queryForObject("SELECT mixtureStatus FROM mulino_inventory_QuantitySegments WHERE ID=?",String.class,merged));assertEquals(BigDecimal.ZERO,runtime.requestContext().run(ctx->{return eligibility.assess(c(),inventory.current(c(),"QuantitySegments",merged),"SELL",customer);}).eligibleQuantity());var facts=runtime.requestContext().run(ctx->{return eligibility.read(c(),"getInventory",item,Map.of("placeId",place),List.of(inventory.current(c(),"QuantitySegments",merged)));});assertEquals("40",facts.values().get("allocationShortageQuantity"));assertEquals("40",facts.values().get("reservationResponsibilityQuantity"));}
